18	/// Identifies an element in the document.
19	///
20	/// A location uniquely identifies an element in the document and lets you
21	/// access its absolute position on the pages. You can retrieve the current
22	/// location with the @here function and the location of a queried or shown
23	/// element with the @content.location[`location()`] method on content.
24	///
25	/// = #short-or-long[Locatable][Locatable elements] <locatable>
26	/// Elements that are automatically assigned a location are called _locatable_
27	/// and can be found with @query[queries]:
28	///
29	/// - In the @reference:model[Model category], the following elements are
30	///   locatable: @asset, @bibliography, @cite, @document, @emph, @enum, @figure,
31	///   @figure.caption, @footnote, @footnote.entry, @heading, @link, @list,
32	///   @outline, @outline.entry, @par, @quote, @ref, @strong, @table, @terms, and
33	///   @title. Most of the elements in the _Model_ category are locatable because
34	///   semantic elements like headings and figures are often
35	///   used with introspection.
36	///
37	/// - In the @reference:text[Text category], the @raw element and the
38	///   decoration elements @underline, @overline, @strike, and @highlight are
39	///   locatable as these are also quite semantic in nature.
40	///
41	/// - In the @reference:introspection[Introspection category], the @metadata
42	///   element is locatable as being queried for is its primary purpose.
43	///
44	/// - In the other categories, most elements are not locatable. Exceptions are
45	///   @math.equation, @image, and @pdf.attach.
46	///
47	/// To find out whether a specific element is locatable, you can try to @query
48	/// for it.
49	///
50	/// Note that you can still observe elements that are not locatable in queries
51	/// through other means, for instance, when they have a label attached to them.
52	#[ty(scope, since = "forever")]
53	#[derive(Copy, Clone, Eq, PartialEq, Hash)]
54	pub struct Location(u128);
55	
56	impl Location {
57	    /// Create a new location from a unique hash.
58	    pub fn new(hash: u128) -> Self {
59	        Self(hash)
60	    }
61	
62	    /// Extract the raw hash.
63	    pub fn hash(self) -> u128 {
64	        self.0
65	    }
66	
67	    /// Produces a well-known variant of this location.
68	    ///
69	    /// This is a synthetic location created from another one and is used, for
70	    /// example, in bibliography management to create individual linkable
71	    /// locations for reference entries from the bibliography's location.
72	    pub fn variant(self, n: usize) -> Self {
73	        Self(typst_utils::hash128(&(self.0, n)))
74	    }
75	}
