334	    type Output = Option<Location>;
335	
336	    fn introspect(
337	        &self,
338	        _: &mut Engine,
339	        introspector: Tracked<dyn Introspector + '_>,
340	    ) -> Self::Output {
341	        introspector.document(self.0)
342	    }
343	
344	    fn diagnose(&self, history: &History<Self::Output>) -> SourceDiagnostic {
345	        format_convergence_warning(
346	            self.0,
347	            self.1,
348	            history,
349	            "path",
350	            |element| eco_format!("document in which the {element} is located"),
351	            |_loc| eco_format!("TODO"),
352	        )
353	    }
354	}
355	
356	/// The warning when an introspection on a [`Location`] did not converge.
357	fn format_convergence_warning<T>(
358	    loc: Location,
359	    span: Span,
360	    history: &History<T>,
361	    output_kind_plural: &str,
362	    format_output_kind: impl FnOnce(&str) -> EcoString,
363	    format_output: impl FnMut(&T) -> EcoString,
364	) -> SourceDiagnostic {
365	    let elem = history.final_introspector().query_first(&Selector::Location(loc));
366	    let kind = match &elem {
367	        Some(content) => content.elem().name(),
368	        None => "element",
369	    };
370	
371	    let what = format_output_kind(kind);
372	    let mut diag = warning!(span, "{what} did not stabilize");
373	
374	    if let Some(elem) = elem
375	        && !elem.span().is_detached()
376	    {
377	        diag.spanned_hint(eco_format!("{kind} was created here"), elem.span());
378	    }
379	
380	    diag.with_hint(history.hint(output_kind_plural, format_output))
381	}
